namespace NotificationApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<NotificationItem> _allNotifications =
    [
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
        new() { Id = 3, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
    ];

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        return Task.FromResult(_allNotifications.ToList());
    }

    /// <summary>
    /// Returns any notifications newer than the given ID.
    /// Randomly generates a new notification ~30% of the time to simulate activity.
    /// </summary>
    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastSeenId)
    {
        if (Random.Shared.NextDouble() < 0.3)
        {
            _allNotifications.Add(new NotificationItem
            {
                Id = _nextId++,
                Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                Timestamp = DateTime.UtcNow
            });
        }

        var newer = _allNotifications.Where(n => n.Id > lastSeenId).ToList();
        return Task.FromResult(newer);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge">@Items.Count</span>
    }
</h1>

@if (Items is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var item in Items.OrderByDescending(n => n.Timestamp))
        {
            <li>
                <strong>@item.Message</strong>
                <span class="timestamp">@item.Timestamp.ToString("g")</span>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<NotificationItem>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch data that was persisted from prerender
        Items ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender,
        // so the polling loop only starts once the page is truly interactive.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var lastId = Items?.Count > 0 ? Items.Max(n => n.Id) : 0;
            var newer = await NotificationService.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                Items!.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

.badge {
    display: inline-flex;
