    background-color: #dc3545;
    border-radius: 999px;
    vertical-align: middle;
    margin-left: 0.4rem;
}

.notification-list {
    list-style: none;
    padding: 0;
}

.notification-list li {
    display: flex;
    justify-content: space-between;
